// SPDX-License-Identifier: GPL-3.0-or-later
// Generates lib/sdrpp/dsp/multirate/decim/taps.g.dart from SDR++
// core/src/dsp/multirate/decim/taps/fir_*.h (the auto-generated "optimized FIR" decimation taps).
//
// Usage: dart run tool/gen_decim_taps.dart [path/to/sdrpp]   (default ~/prj/sdrpp)
import 'dart:io';

void main(List<String> args) {
  final home = Platform.environment['HOME'] ?? '.';
  final root = args.isNotEmpty ? args[0] : '$home/prj/sdrpp';
  final dir = Directory('$root/core/src/dsp/multirate/decim/taps');
  final files = dir.listSync().whereType<File>().where((f) => f.path.endsWith('.h')).toList()
    ..sort((a, b) => a.path.compareTo(b.path));
  final nameRe = RegExp(r'const unsigned int (fir_\d+_\d+)_len\s*=\s*(\d+);');
  final numRe = RegExp(r'^\s*(-?\d+(?:\.\d+)?(?:[eE][-+]?\d+)?)\s*,?\s*$');

  final out = StringBuffer()
    ..writeln('// SPDX-License-Identifier: GPL-3.0-or-later')
    ..writeln('// GENERATED by tool/gen_decim_taps.dart from SDR++ '
        'core/src/dsp/multirate/decim/taps/*.h — DO NOT EDIT.')
    ..writeln('// Original header: "This file was auto-generated by the magic optimized FIR script."')
    ..writeln('// ignore_for_file: constant_identifier_names')
    ..writeln();
  int total = 0;
  for (final f in files) {
    final src = f.readAsStringSync().replaceAll('\r', '');
    final m = nameRe.firstMatch(src);
    if (m == null) throw StateError('No length in ${f.path}');
    final name = m.group(1)!;
    final len = int.parse(m.group(2)!);
    final body = src.substring(src.indexOf('{', src.indexOf('${name}_taps')) + 1, src.indexOf('};'));
    final vals = <String>[];
    for (final line in body.split('\n')) {
      if (line.trim().isEmpty) continue;
      final nm = numRe.firstMatch(line);
      if (nm == null) throw StateError('Bad line in ${f.path}: "$line"');
      vals.add(nm.group(1)!);
    }
    if (vals.length != len) throw StateError('${f.path}: expected $len taps, got ${vals.length}');
    total += len;
    final camel = name.replaceAllMapped(RegExp(r'_(\d)'), (x) => '_${x.group(1)}');
    out
      ..writeln('/// ${f.uri.pathSegments.last}')
      ..writeln('const int ${camel}_len = $len;')
      ..writeln('const List<double> ${camel}_taps = [');
    for (final v in vals) {
      out.writeln('  ${v.startsWith('-') || v.contains('.') ? v : '$v.0'},');
    }
    out
      ..writeln('];')
      ..writeln();
  }
  final dst = File('lib/sdrpp/dsp/multirate/decim/taps.g.dart');
  dst.parent.createSync(recursive: true);
  dst.writeAsStringSync(out.toString());
  stdout.writeln('Wrote ${dst.path}: ${files.length} filters, $total taps');
}
